style.css:
@-moz-document domain("wattpad.com") {
/* Wattpad Cyberpunk Theme */
    body {
        background-color: #000000; /* Black background for contrast */
        color: #00FFFF; /* Neon blue text */
        font-family: "Arial", sans-serif; /* Clean and bold font */
    }

    a {
        color: #00FFFF; /* Neon blue for links */
        text-decoration: none;
    }

    a:hover {
        color: #FF00FF; /* Neon magenta hover effect */
    }

    header, footer {
        background-color: #101010; /* Dark background for header and footer */
        border-bottom: 2px solid #00FFFF; /* Neon blue separator */
    }

    .nav-bar {
        background-color: #101010; /* Match header */
        color: #00FFFF;
    }

    .story-card {
        background-color: #1A1A1A; /* Dark grey background for story cards */
        border: 1px solid #00FFFF; /* Neon blue borders */
        color: #FFFFFF;
    }

    .story-card:hover {
        background-color: #101010; /* Darker hover effect */
        border-color: #FF00FF; /* Neon magenta on hover */
    }

    h1, h2, h3, h4, h5, h6 {
        color: #00FFFF; /* Neon blue for headings */
        text-shadow: 0px 0px 5px #00FFFF; /* Glow effect */
    }

    button {
        background-color: #00FFFF; /* Neon blue button */
        color: #000000; /* Black text */
        border: none;
        border-radius: 5px;
        padding: 10px 15px;
        cursor: pointer;
        transition: background-color 0.3s ease;
    }

    button:hover {
        background-color: #FF00FF; /* Neon magenta on hover */
    }

    input, textarea {
        background-color: #1A1A1A; /* Dark grey inputs */
        color: #FFFFFF;
        border: 1px solid #00FFFF; /* Neon blue border */
    }

    input:focus, textarea:focus {
        outline: none;
        border-color: #FF00FF; /* Neon magenta on focus */
    }

    ::-webkit-scrollbar {
        width: 10px;
        background-color: #101010; /* Match the theme */
    }

    ::-webkit-scrollbar-thumb {
        background-color: #00FFFF; /* Neon blue scrollbar */
        border-radius: 10px;
    }

    ::-webkit-scrollbar-thumb:hover {
        background-color: #FF00FF; /* Neon magenta on hover */
    }
}
